  <script dangerouslySetInnerHTML={{__html:"\r\n  (function(){\r\n    var track    = document.getElementById('mentorsTrack');\r\n    var prevBtn  = document.getElementById('mentorsPrevBtn');\r\n    var nextBtn  = document.getElementById('mentorsNextBtn');\r\n    var dotsWrap = document.getElementById('mentorsDots');\r\n\r\n    if (!track) return;\r\n\r\n    var cards = track.querySelectorAll('.mentor-card');\r\n    var totalCards = cards.length;\r\n\r\n    /* -- Responsive: how many cards visible -- */\r\n    function visibleCount() {\r\n      var w = window.innerWidth;\r\n      if (w >= 1100) return 4;\r\n      if (w >= 700)  return 2;\r\n      return 1;\r\n    }\r\n\r\n    var currentIndex = 0;\r\n\r\n    /* -- Build dots -- */\r\n    function buildDots() {\r\n      dotsWrap.innerHTML = '';\r\n      var pages = Math.ceil(totalCards / visibleCount());\r\n      for (var i = 0; i < pages; i++) {\r\n        var btn = document.createElement('button');\r\n        btn.className = 'mentors-dot' + (i === 0 ? ' active' : '');\r\n        btn.setAttribute('aria-label', 'Go to page ' + (i + 1));\r\n        btn.dataset.page = i;\r\n        btn.addEventListener('click', function(){\r\n          goTo(+this.dataset.page * visibleCount());\r\n          restartAuto();\r\n        });\r\n        dotsWrap.appendChild(btn);\r\n      }\r\n    }\r\n\r\n    function updateDots() {\r\n      var vc = visibleCount();\r\n      var activePage = Math.round(currentIndex / vc);\r\n      var allDots = dotsWrap.querySelectorAll('.mentors-dot');\r\n      allDots.forEach(function(d, i){\r\n        d.classList.toggle('active', i === activePage);\r\n      });\r\n    }\r\n\r\n    function goTo(index) {\r\n      var vc = visibleCount();\r\n      var maxIndex = totalCards - vc;\r\n      currentIndex = Math.max(0, Math.min(index, maxIndex));\r\n\r\n      /* card width + gap */\r\n      var cardEl = cards[0];\r\n      var style = window.getComputedStyle(cardEl);\r\n      var cardW = cardEl.offsetWidth + parseInt(style.marginRight || 0, 10);\r\n      var gap = 24;\r\n      var offset = currentIndex * (cardEl.offsetWidth + gap);\r\n\r\n      track.style.transform = 'translateX(-' + offset + 'px)';\r\n\r\n      prevBtn.disabled = (currentIndex === 0);\r\n      nextBtn.disabled = (currentIndex >= totalCards - vc);\r\n      updateDots();\r\n    }\r\n\r\n    prevBtn.addEventListener('click', function(){\r\n      goTo(currentIndex - visibleCount());\r\n      restartAuto();\r\n    });\r\n    nextBtn.addEventListener('click', function(){\r\n      goTo(currentIndex + visibleCount());\r\n      restartAuto();\r\n    });\r\n\r\n    track.addEventListener('mouseenter', function () { if (autoTimer) clearInterval(autoTimer); });\r\n    track.addEventListener('mouseleave', restartAuto);\r\n    track.addEventListener('touchstart', function () { if (autoTimer) clearInterval(autoTimer); }, { passive: true });\r\n    track.addEventListener('touchend', restartAuto, { passive: true });\r\n\r\n    window.addEventListener('resize', function(){\r\n      buildDots();\r\n      goTo(0);\r\n      restartAuto();\r\n    });\r\n\r\n    buildDots();\r\n    goTo(0);\r\n\r\n    var autoTimer = null;\r\n    var autoDelay = 3500;\r\n    function restartAuto() {\r\n      if (autoTimer) clearInterval(autoTimer);\r\n      if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;\r\n      autoTimer = setInterval(function () {\r\n        var vc = visibleCount();\r\n        var next = currentIndex + vc;\r\n        if (next >= totalCards) next = 0;\r\n        goTo(next);\r\n      }, autoDelay);\r\n    }\r\n    restartAuto();\r\n  })();\r\n  "}} />
    
    
    
    
    


