  <section className="about-mission-section">
    <div className="container">
      <div className="about-mission-shell">
        <div className="about-mission-content-card">
          <span className="about-mission-eyebrow">Mission &amp; Values</span>
          <h2 className="about-mission-title">Our Mission</h2>

          <div className="about-mission-copy">
            <p>DizitalAdda exists to close the gap between what India's education system teaches and what India's job market actually requires. We believe that every student — regardless of their academic background, city, or financial position — deserves access to practical, current, career-ready training that leads directly to employment.</p>
            <p>Our courses are designed with one outcome in mind: your first job, your first promotion, and your long-term career independence.</p>
            <p>We measure our success not by enrolment numbers, but by the number of students who are employed, earning, and growing in their careers within 6 months of completing their training.</p>
          </div>
        </div>

        <div className="about-mission-side-column" aria-label="Mission priorities">
          <article className="about-mission-focus-card">
            <span className="about-mission-focus-icon"><i className="bi bi-briefcase-fill"></i></span>
            <strong className="about-mission-focus-title">Career-Ready Outcomes</strong>
            <p className="about-mission-focus-copy">Every course is built around employability, promotion-readiness, and long-term professional independence.</p>
          </article>

          <article className="about-mission-focus-card">
            <span className="about-mission-focus-icon"><i className="bi bi-globe-central-south-asia"></i></span>
            <strong className="about-mission-focus-title">Accessible Learning</strong>
            <p className="about-mission-focus-copy">Opportunity should not be limited by academic background, city, or financial position.</p>
          </article>

          <article className="about-mission-focus-card">
            <span className="about-mission-focus-icon"><i className="bi bi-bar-chart-line-fill"></i></span>
            <strong className="about-mission-focus-title">Measured by Student Growth</strong>
            <p className="about-mission-focus-copy">We judge success by employment, earnings, and career progress within six months of training completion.</p>
          </article>
        </div>
      </div>
    </div>
  </section>
