   <script dangerouslySetInnerHTML={{__html:"\r\n  (function(){\r\n\r\n    // Direct to Google Apps Script with no-cors (bypasses CORS entirely)\r\n    var SHEET_URL = '/api/forms/book-demo';\r\n\r\n    /* ------------------------------\r\n       Calendar\r\n    ------------------------------ */\r\n    var todayRaw   = new Date();\r\n    todayRaw.setHours(0,0,0,0);\r\n    var viewYear   = todayRaw.getFullYear();\r\n    var viewMonth  = todayRaw.getMonth(); // 0-based\r\n    var selectedDate = null;\r\n\r\n    var MONTHS = ['January','February','March','April','May','June',\r\n                  'July','August','September','October','November','December'];\r\n    var DAYS   = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];\r\n\r\n    function fmtDisplay(d){\r\n      return DAYS[d.getDay()] + ', ' + d.getDate() + ' ' + MONTHS[d.getMonth()] + ' ' + d.getFullYear();\r\n    }\r\n    function fmtISO(d){\r\n      var mm = String(d.getMonth()+1).padStart(2,'0');\r\n      var dd = String(d.getDate()).padStart(2,'0');\r\n      return d.getFullYear() + '-' + mm + '-' + dd;\r\n    }\r\n    var CAL_ICON = '<svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"1.8\" stroke=\"currentColor\" style=\"width:16px;height:16px;flex-shrink:0\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M6.75 3v2.25M17.25 3v2.25M3 18.75V7.5a2.25 2.25 0 012.25-2.25h13.5A2.25 2.25 0 0121 7.5v11.25m-18 0A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75m-18 0v-7.5A2.25 2.25 0 015.25 9h13.5A2.25 2.25 0 0121 11.25v7.5\"/></svg>';\r\n\r\n    function renderCalendar(){\r\n      var grid  = document.getElementById('bdCalGrid');\r\n      var label = document.getElementById('bdCalMonthLabel');\r\n      label.textContent = MONTHS[viewMonth] + ' ' + viewYear;\r\n      grid.innerHTML = '';\r\n\r\n      var firstDay    = new Date(viewYear, viewMonth, 1).getDay();\r\n      var daysInMonth = new Date(viewYear, viewMonth + 1, 0).getDate();\r\n\r\n      for(var i = 0; i < firstDay; i++){\r\n        var empty = document.createElement('div');\r\n        empty.className = 'bd-cal-day empty';\r\n        grid.appendChild(empty);\r\n      }\r\n\r\n      for(var d = 1; d <= daysInMonth; d++){\r\n        var cell     = document.createElement('button');\r\n        cell.type    = 'button';\r\n        cell.textContent = d;\r\n        var cellDate = new Date(viewYear, viewMonth, d);\r\n        cellDate.setHours(0,0,0,0);\r\n\r\n        var cls = 'bd-cal-day';\r\n        var isPast = cellDate.getTime() < todayRaw.getTime();\r\n        if(isPast) cls += ' disabled';\r\n        if(cellDate.getTime() === todayRaw.getTime()) cls += ' today';\r\n        if(selectedDate && cellDate.getTime() === selectedDate.getTime()) cls += ' selected';\r\n        cell.className = cls;\r\n\r\n        if(!isPast){\r\n          (function(dt){\r\n            cell.addEventListener('click', function(){ selectDate(dt); });\r\n          })(cellDate);\r\n        }\r\n        grid.appendChild(cell);\r\n      }\r\n    }\r\n\r\n    function selectDate(dt){\r\n      selectedDate = dt;\r\n      document.getElementById('bd_date').value = fmtISO(dt);\r\n      renderCalendar();\r\n      // Update calendar selected-display\r\n      document.getElementById('bdSelectedDisplay').innerHTML =\r\n        CAL_ICON + '<span>Selected: <span class=\"bd-sel-date\">' + fmtDisplay(dt) + '</span></span>';\r\n      // Update form date echo\r\n      var echo = document.getElementById('bdFormDateEcho');\r\n      document.getElementById('bdFormDateText').textContent = fmtDisplay(dt);\r\n      echo.classList.add('filled');\r\n      // Clear any status error about date\r\n      document.getElementById('bdStatus').innerHTML = '';\r\n    }\r\n\r\n    document.getElementById('bdCalPrev').addEventListener('click', function(){\r\n      viewMonth--;\r\n      if(viewMonth < 0){ viewMonth = 11; viewYear--; }\r\n      renderCalendar();\r\n    });\r\n    document.getElementById('bdCalNext').addEventListener('click', function(){\r\n      viewMonth++;\r\n      if(viewMonth > 11){ viewMonth = 0; viewYear++; }\r\n      renderCalendar();\r\n    });\r\n\r\n    renderCalendar();\r\n\r\n    /* ------------------------------\r\n       Form submission\r\n    ------------------------------ */\r\n    var form      = document.getElementById('bookDemoForm');\r\n    var btnText   = document.getElementById('bdBtnText');\r\n    var btnLoader = document.getElementById('bdBtnLoader');\r\n    var status    = document.getElementById('bdStatus');\r\n    var submitBtn = document.getElementById('bdSubmitBtn');\r\n\r\n    form.addEventListener('submit', function(e){\r\n      e.preventDefault();\r\n\r\n      if(!selectedDate){\r\n        status.innerHTML = '<span class=\"bdf-error\">Please select a preferred date from the calendar on the left.</span>';\r\n        document.querySelector('.bd-calendar-panel').scrollIntoView({behavior:'smooth', block:'center'});\r\n        return;\r\n      }\r\n      if(!form.checkValidity()){ form.reportValidity(); return; }\r\n\r\n      if(!SHEET_URL){\r\n        status.innerHTML = '<span class=\"bdf-error\">Submission URL not configured. Please contact us on WhatsApp.</span>';\r\n        return;\r\n      }\r\n\r\n      btnText.style.display   = 'none';\r\n      btnLoader.style.display = 'inline';\r\n      submitBtn.disabled      = true;\r\n      status.innerHTML        = '';\r\n\r\n      var data = new FormData(form);\r\n      var payload = {};\r\n      data.forEach(function(v,k){ payload[k] = v; });\r\n      payload.date      = fmtISO(selectedDate);\r\n      payload.timestamp = new Date().toLocaleString('en-IN',{timeZone:'Asia/Kolkata'});\r\n      payload.source    = window.location.href;\r\n\r\n      fetch(SHEET_URL, {\r\n        method: 'POST',\r\n        mode: 'no-cors',\r\n        body: JSON.stringify(payload),\r\n        headers: { 'Content-Type': 'text/plain;charset=utf-8' }\r\n      })\r\n      .then(function(){\r\n        // no-cors returns an opaque response ? data was sent, assume success\r\n        status.innerHTML = '<span class=\"bdf-success\">? Demo booked for <strong>' + fmtDisplay(selectedDate) + '</strong>! We\\'ll call you within 24 hours to confirm your slot.</span>';\r\n        form.reset();\r\n        selectedDate = null;\r\n        document.getElementById('bd_date').value = '';\r\n        var echo = document.getElementById('bdFormDateEcho');\r\n        document.getElementById('bdFormDateText').textContent = '\\u2190 Pick a date from the calendar';\r\n        echo.classList.remove('filled');\r\n        document.getElementById('bdSelectedDisplay').innerHTML =\r\n          CAL_ICON + '<span>Select a date to book your demo</span>';\r\n        renderCalendar();\r\n      })\r\n      .catch(function(err){\r\n        status.innerHTML = '<span class=\"bdf-error\">Could not submit. Please WhatsApp us to book your demo.</span>';\r\n      })\r\n      .finally(function(){\r\n        btnText.style.display   = 'inline';\r\n        btnLoader.style.display = 'none';\r\n        submitBtn.disabled      = false;\r\n      });\r\n    });\r\n  })();\r\n  "}} />




    
    
    
    
